CREATE TABLE page_spec_imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), checksum text NOT NULL UNIQUE, sources jsonb NOT NULL, summary jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE page_specs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), import_id uuid NOT NULL REFERENCES page_spec_imports(id), page_id uuid NOT NULL REFERENCES pages(id), path text NOT NULL, specification jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(import_id,page_id));
CREATE TABLE pipeline_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), spec_id uuid NOT NULL REFERENCES page_specs(id), page_id uuid NOT NULL REFERENCES pages(id), base_revision_id uuid, result_revision_id uuid REFERENCES revisions(id), provider text NOT NULL CHECK(provider IN ('bedrock','openrouter')), model text NOT NULL, image_model text, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','review','failed','cancelled')), review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','accepted','rejected')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX pipeline_active_page ON pipeline_runs(page_id) WHERE status IN ('queued','running');
CREATE TABLE pipeline_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES pipeline_runs(id), kind text NOT NULL CHECK(kind IN ('blueprint','section','asset')), section_id text, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed')), attempts int NOT NULL DEFAULT 0, lease_token uuid, lease_until timestamptz, request_snapshot jsonb, result jsonb, usage jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX pipeline_task_identity ON pipeline_tasks(run_id,kind,COALESCE(section_id,''));
CREATE TABLE generated_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES pipeline_runs(id), section_id text, hash text NOT NULL, filename text NOT NULL, mime text NOT NULL, width int NOT NULL, height int NOT NULL, alt text NOT NULL, source_prompt text NOT NULL, provider text NOT NULL, model text NOT NULL, review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','accepted','rejected')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE newsletter_subscribers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','unsubscribed','suppressed')), confirmation_hash text, confirmation_expires_at timestamptz, unsubscribe_hash text NOT NULL, confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE email_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient text NOT NULL, subject text NOT NULL, body text NOT NULL, purpose text NOT NULL, dedupe_key text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sending','sent','failed','suppressed')), attempts int NOT NULL DEFAULT 0, provider_message_id text, error text, next_attempt_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vacancies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, department text NOT NULL, location text NOT NULL, employment_type text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'closed' CHECK(status IN ('open','closed')), verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE career_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES vacancies(id), email text NOT NULL, name text NOT NULL, phone text, cover_message text, consent_at timestamptz NOT NULL, cv_filename text NOT NULL, cv_hash text NOT NULL, cv_mime text NOT NULL, scan_result text NOT NULL CHECK(scan_result='clean'), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','reviewing','interview','declined','hired')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(vacancy_id,email));
